export async function retry<T>(
  fn: () => Promise<T>,
  options: {
    maxAttempts: number
    baseDelayMs: number
    shouldRetry: (error: unknown) => boolean
  }
): Promise<T> {
  let lastError: unknown
  for (let attempt = 1; attempt <= options.maxAttempts; attempt++) {
    try {
      return await fn()
    } catch (err) {
      lastError = err
      if (!options.shouldRetry(err)) throw err
    }
  }
  throw lastError
}

